import java.util.*;class Solution{boolean ok(String s){int b=0;for(char c:s.toCharArray()){if(c=='(')b++;else if(c==')'&&--b<0)return false;}return b==0;}public List<String> removeInvalidParentheses(String s){List<String>o=new ArrayList<>();Queue<String>q=new ArrayDeque<>();Set<String>v=new HashSet<>();q.add(s);v.add(s);boolean found=false;while(!q.isEmpty()&&!found){int z=q.size();while(z-->0){String x=q.remove();if(ok(x)){o.add(x);found=true;}if(found)continue;for(int i=0;i<x.length();i++)if(x.charAt(i)=='('||x.charAt(i)==')'){String y=x.substring(0,i)+x.substring(i+1);if(v.add(y))q.add(y);}}}return o;}}
